SELECT ROUND(100.0 * AVG(CASE WHEN c.uuid IN (
    SELECT f.uuid
    FROM foreign_data AS f
    WHERE f.language = 'Chinese Simplified'
) THEN 1 ELSE 0 END), 2) AS percentage
FROM cards AS c;

SELECT DISTINCT replace(text, char(10), ' ') AS rules_text
FROM cards
WHERE name = 'Benalish Knight';

